                                                                                                                                                                                                                                           '面的整個實體或開放面/殼建立獨立的標準網格。線性偏轉0.01–1000mm，角度5–90°，對角線<=10000mm，線性>=對角線/2000；輸出1–20000個三角形。保留並隱藏原始內容；應用一次完整的家長/自己的放置。本機近似參數無法證明全域偏差或與 '
                                                                                                                                                                                                                                           'Fusion '
                                                                                                                                                                                                                                           '設定的等效性。沒有四邊形、面組、每個面顏色、最大邊緣/長寬比控制、連結歷史記錄或專門的重新編輯。',
